contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint putAmount, uint lockTime) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (putAmount)); require(putAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= putAmount, "insufficient balance");
        require(putAmount > 0, "amount must be positive");

        uint contractBalanceBefore = address(c).balance;
        (uint unlockBefore, uint callerBalanceBefore) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        c.Put{value: putAmount}(lockTime); if (__ESBMC_reverted()) return;

        (uint unlockAfter, uint callerBalanceAfter) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalanceAfter = address(c).balance;

        assert(callerBalanceAfter >= callerBalanceBefore && contractBalanceAfter >= contractBalanceBefore);
    }

    receive() external payable {}
}

