pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 putAmount, uint256 lockTime) internal {
        putAmount = bound(putAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= putAmount);
        vm.assume(putAmount > 0);
        uint contractBalanceBefore = address(c).balance;
        uint256 unlockBefore;
        uint256 callerBalanceBefore;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockBefore = __r0; callerBalanceBefore = __r1; } catch { return; }
        try c.Put{value: putAmount}(lockTime) {} catch { return; }
        uint256 unlockAfter;
        uint256 callerBalanceAfter;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockAfter = __r0; callerBalanceAfter = __r1; } catch { return; }
        uint contractBalanceAfter = address(c).balance;
        assertTrue(callerBalanceAfter >= callerBalanceBefore && contractBalanceAfter >= contractBalanceBefore);
    }

    function testFuzz_run(uint256 putAmount, uint256 lockTime) public {
        _run(putAmount, lockTime);
    }

    receive() external payable {}
}
